#!/usr/bin/env python3
"""Extract Capsaicin's two lookup-jitter dimensions; no runtime generation.

Usage: python3 generate_blue_noise.py /path/to/Capsaicin
The pinned source revision and license are recorded in README.md.
"""

import re
import sys
from pathlib import Path

source = Path(sys.argv[1]) / "src/core/src/components/blue_noise_sampler/blue_noise_sampler_samples.h"
text = source.read_text()


def table(name, size):
    match = re.search(r"static const uint32_t " + name + r"\[[^\]]+\]\s*=\s*\{([^}]+)\}", text)
    values = [int(value) for value in match[1].split(",") if value.strip()]
    assert len(values) == size and all(0 <= value < 256 for value in values)
    return values


sobol = table("Sobol256x256", 256 * 256)
ranking = table("RankingTiles", 128 * 128 * 8)
scrambling = table("ScramblingTiles", 128 * 128 * 8)
# Exact evaluation of the upstream sampler at index 0, dimensions 0 and 1.
# Frame-dependent golden-ratio rotation remains in the shader, as upstream.
samples = [
    sobol[dimension + ranking[pixel * 8 + dimension] * 256] ^ scrambling[pixel * 8 + dimension]
    for pixel in range(128 * 128)
    for dimension in range(2)
]
words = [sum(samples[i + j] << (8 * j) for j in range(4)) for i in range(0, len(samples), 4)]
header = """// Derived from AMD Capsaicin; copyright 2023 Advanced Micro Devices, Inc.
// MIT license: see LICENSE.txt. Generated by generate_blue_noise.py.
// Two 8-bit dimensions per pixel, two pixels per 32-bit word.
#pragma once

#include <stdint.h>

static const uint32_t AMD_GI_BLUE_NOISE[8192] = {
"""
header += "\n".join("\t" + ", ".join(f"0x{word:08x}u" for word in words[i:i + 8]) + "," for i in range(0, len(words), 8))
header += "\n};\n"
Path(__file__).with_name("blue_noise.h").write_text(header)
